{"type":"tool_use","timestamp":1787360131299,"sessionID":"ses_fd9096bbeffeOICkIcZGQdx27o","part":{"type":"tool","tool":"write","callID":"chatcmpl-tool-0f397cd371744cb7a5aea15b84b67c0e","state":{"status":"completed","input":{"content":"export function applyVolumeDiscount(subtotal: number, quantity: number): number {
  if (!Number.isFinite(subtotal) || !Number.isFinite(quantity)) {
    throw new RangeError("subtotal and quantity must be finite numbers");
  }
  if (subtotal < 0 || quantity < 0) {
    throw new RangeError("subtotal and quantity must be non-negative");
  }

  let rate = 0;
  if (quantity >= 50) {
    rate = 0.1;
  } else if (quantity >= 10) {
    rate = 0.05;
  }

  const discounted = subtotal * (1 - rate);
  return Math.round((discounted + Number.EPSILON) * 100) / 100;
}
