{"type":"tool_use","timestamp":1787360377096,"sessionID":"ses_fd905aa19ffeoWTNO5iMwC6g2J","part":{"type":"tool","tool":"write","callID":"chatcmpl-tool-11bd33cd7cb8438885188d3c0210565e","state":{"status":"completed","input":{"content":"export function parseMoney(input: string): number {
  if (typeof input !== "string" || input.trim() === "") {
    throw new TypeError("invalid money amount");
  }

  const normalized = input.replace(/^\s*\$\s?/, "").trim();

  if (normalized === "") {
    throw new TypeError("invalid money amount");
  }

  if (!/^-?\d{1,3}(,\d{3})*(\.\d+)?$/.test(normalized) && !/^-?\d+(\.\d+)?$/.test(normalized)) {
    throw new TypeError("invalid money amount");
  }

  const cleaned = normalized.replace(/,/g, "");
  const value = Number.parseFloat(cleaned);

  if (!Number.isFinite(value)) {
    throw new TypeError("invalid money amount");
  }

  const rounded = Math.round((value + Number.EPSILON) * 100) / 100;

  return rounded;
}
