  assert.equal(applyVolumeDiscount(100, 50), 90);
});

test("rejects negative inputs", () => {
  assert.throws(() => applyVolumeDiscount(-1, 1), RangeError);
  assert.throws(() => applyVolumeDiscount(10, -1), RangeError);
});
