{"type":"tool_use","timestamp":1787361363390,"sessionID":"ses_fd8f6e905ffeNoMSinZzMb31SK","part":{"type":"tool","tool":"write","callID":"chatcmpl-tool-258993614d5744ca947af03f0e3db8d6","state":{"status":"completed","input":{"content":"export function parseMoney(input: string): number {
  if (typeof input !== "string" || input.trim() === "") {
    throw new TypeError("invalid money amount");
  }
  const m = input.match(
    /^\s*\$?(-?)((?:[1-9]\d{0,2}(?:,\d{3})*)|0)(?:\.(\d{1,2}))?\s*$/,
  );
  if (!m) {
    throw new TypeError("invalid money amount");
  }
  const sign = m[1] === "-" ? -1 : 1;
  const intPart = m[2].replace(/,/g, "");
  const frac = m[3] ?? "";
  const value =
    sign * (Number(intPart) + (frac ? Number(frac) / 10 ** frac.length : 0));
  if (!Number.isFinite(value)) {
    throw new TypeError("invalid money amount");
  }
  return Math.round(value * 100) / 100;
}
