{"type":"tool_use","timestamp":1787362734389,"sessionID":"ses_fd8e1c936ffePknyjG8Mv1I9JU","part":{"type":"tool","tool":"write","callID":"chatcmpl-tool-bf0fd127135f9072","state":{"status":"completed","input":{"content":"export function parseMoney(input: string): number {
  if (typeof input !== "string" || input.trim() === "") {
    throw new TypeError("invalid money amount");
  }
  const trimmed = input.trim();
  if (!/^-?\$?(?:\d{1,3}(?:,\d{3})*|\d+)(\.\d+)?$/.test(trimmed)) {
    throw new TypeError("invalid money amount");
  }
  const normalized = trimmed.replace(/^\$/, "").replace(/,/g, "");
  const value = Number(normalized);
  if (!Number.isFinite(value)) {
    throw new TypeError("invalid money amount");
  }
  const rounded = (Math.sign(value) * Math.round(Math.abs(value) * 100)) / 100;
  return rounded;
}
